import React from 'react';
import DashboardChart from './DashboardChart';

const SupervisorReports = ({ properties, adminInfo }) => {
  // تصفية العقارات المباعة (محاكاة: نفترض أن المشرف يرى كل المبيعات أو المرتبطة به)
  const soldProperties = properties.filter(p => {
    const isSold = p.availability === 'مباعة';
    if (adminInfo?.role === 'supervisor') {
      return isSold && p.addedBy === adminInfo.username;
    }
    return isSold;
  });
  
  const totalRevenue = soldProperties.reduce((acc, curr) => acc + (Number(curr.price) || 0), 0);
  const totalSales = soldProperties.length;

  // تجهيز بيانات الرسم البياني: المبيعات حسب المدينة
  const salesByCity = soldProperties.reduce((acc, curr) => {
    const city = curr.location?.city || 'غير محدد';
    acc[city] = (acc[city] || 0) + 1;
    return acc;
  }, {});
  
  const chartData = Object.entries(salesByCity).map(([label, value]) => ({ label, value }));

  return (
    <div className="container fade-in">
      <h2 className="mb-4">📊 تقارير المبيعات - {adminInfo?.name || 'المشرف'}</h2>
      
      <div className="row mb-4">
        <div className="col-md-6">
          <div className="card text-white bg-success shadow-sm h-100">
            <div className="card-body">
              <h5 className="card-title">إجمالي العقارات المباعة</h5>
              <p className="card-text display-4">{totalSales} عقار</p>
            </div>
          </div>
        </div>
        <div className="col-md-6">
          <div className="card text-white bg-primary shadow-sm h-100">
            <div className="card-body">
              <h5 className="card-title">إجمالي الإيرادات المحققة</h5>
              <p className="card-text display-4">{totalRevenue.toLocaleString()} ج</p>
            </div>
          </div>
        </div>
      </div>

      <div className="row">
        <div className="col-md-8 mb-4">
           <div className="card shadow-sm h-100">
             <div className="card-header bg-light fw-bold">📋 سجل العمليات الناجحة</div>
             <div className="card-body p-0">
               <div className="table-responsive">
                 <table className="table table-hover mb-0 align-middle">
                   <thead className="table-light">
                     <tr>
                       <th>العقار</th>
                       <th>الموقع</th>
                       <th>السعر</th>
                       <th>الحالة</th>
                       {adminInfo?.role === 'admin' && <th>تمت الإضافة بواسطة</th>}
                     </tr>
                   </thead>
                   <tbody>
                     {soldProperties.length > 0 ? soldProperties.map(p => (
                       <tr key={p.id}>
                         <td>{p.type}</td>
                         <td>{p.location?.city}</td>
                         <td className="text-success fw-bold">{p.price?.toLocaleString()} ج</td>
                         <td><span className="badge bg-success">تم البيع</span></td>
                         {adminInfo?.role === 'admin' && <td><span className="badge bg-secondary">{p.addedBy || 'غير معروف'}</span></td>}
                       </tr>
                     )) : (
                       <tr><td colSpan={adminInfo?.role === 'admin' ? "5" : "4"} className="text-center py-4 text-muted">لا توجد مبيعات مسجلة بعد</td></tr>
                     )}
                   </tbody>
                 </table>
               </div>
             </div>
           </div>
        </div>
        <div className="col-md-4 mb-4"><DashboardChart data={chartData} title="المبيعات حسب المنطقة" /></div>
      </div>
    </div>
  );
};

export default SupervisorReports;
